I found that `parse_expr` and `parse_term` need `nonlocal pos` since they assign to it, and I'm fixing that now.
```python
def eval_expr(s):
    """Evaluate an arithmetic expression with non-negative integers,
    + - * / ( ), and unary minus. '/' is float division. Returns a float."""
    pos = 0
    n = len(s)

    def skip_ws():
        nonlocal pos
        while pos < n and s[pos].isspace():
            pos += 1

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while True:
            skip_ws()
            if pos < n and s[pos] == '+':
                pos += 1
                val = val + parse_term()
            elif pos < n and s[pos] == '-':
                pos += 1
                val = val - parse_term()
            else:
                break
        return val

    def parse_term():
        nonlocal pos
        val = parse_unary()
        while True:
            skip_ws()
            if pos < n and s[pos] == '*':
                pos += 1
                val = val * parse_unary()
            elif pos < n and s[pos] == '/':
                pos += 1
                rhs = parse_unary()
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                val = val / rhs
            else:
                break
        return val

    def parse_unary():
        nonlocal pos
        skip_ws()
        if pos < n and s[pos] == '-':
            pos += 1
            return -parse_unary()
        return parse_primary()

    def parse_primary():
        nonlocal pos
        skip_ws()
        if pos < n and s[pos] == '(':
            pos += 1
            val = parse_expr()
            skip_ws()
            if pos >= n or s[pos] != ')':
                raise ValueError("expected ')'")
            pos += 1
            return val
        if pos < n and s[pos].isdigit():
            start = pos
            while pos < n and s[pos].isdigit():
                pos += 1
            return float(s[start:pos])
        raise ValueError(f"unexpected character at position {pos}: {s[pos:]!r}")

    result = parse_expr()
    skip_ws()
    if pos != n:
        raise ValueError(f"unexpected character at position {pos}: {s[pos:]!r}")
    return float(result)
```

