def topo_count(n, edges):
    """Count distinct topological orderings of a DAG with nodes 0..n-1."""
    pred = [0] * n  # bitmask of each node's direct predecessors
    for u, v in edges:
        pred[v] |= 1 << u

    size = 1 << n
    dp = [0] * size
    dp[0] = 1
    for mask in range(size):
        if dp[mask] == 0:
            continue
        for v in range(n):
            bit = 1 << v
            if not mask & bit and (pred[v] & mask) == pred[v]:
                dp[mask | bit] += dp[mask]
    return dp[size - 1]
